// 1. Service-side OpenTelemetry / Prometheus Histogram definition
const httpDuration = new client.Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP latency distribution in seconds',
  labelNames: ['service', 'route', 'status_class'], // Bounded cardinality!
  buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5]
});

// 2. PromQL: Fleet-wide p99 latency over a 5-minute sliding window
// histogram_quantile(0.99, sum by (le, route) (rate(http_request_duration_seconds_bucket[5m])))

// W3C Traceparent Header Format:
// version (00) | 16-byte trace_id | 8-byte parent_span_id | flags (01 = sampled)
// traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01

# OpenTelemetry Collector Tail-Based Sampling Policy
processors:
  tail_sampling:
    decision_wait: 10s
    num_traces: 100000
    policies:
      - name: keep-errors
        type: status_code
        status_code: { status_codes: [ERROR] }
      - name: keep-high-latency
        type: latency
        latency: { threshold_ms: 500 }
      - name: baseline-probabilistic
        type: probabilistic
        probabilistic: { sampling_percentage: 1.0 }
